(function(root){
 function position(moving,corner,reference,refCorner,dx,dy){const p=moving.points[corner],q=reference?reference.points[refCorner]:{x:0,y:0};if(!p||!q||![dx,dy].every(Number.isFinite))throw Error('Wybierz narożniki i wpisz odległości X/Y.');const x=(reference?.x||0)+q.x+dx-p.x,y=(reference?.y||0)+q.y+dy-p.y;if(Math.abs(x)>200000||Math.abs(y)>200000)throw Error('Położenie przekracza zakres ±200000 mm.');return {x,y};}
 if(typeof module!=='undefined'){module.exports={position};return;}
 let opened=false,project=null;const selections=new Map();
 const original=renderPlan;
 renderPlan=function(){original();const panel=document.querySelector('.room-placement'),svg=document.getElementById('planSvg');if(!panel||!svg)return;const r=room();if(project!==data){project=data;selections.clear();opened=false;}panel.open=opened;
 const corners=q=>q.points.map((_,i)=>`<option value="${i}">N${i+1} · początek ${String.fromCharCode(65+i)}</option>`).join('');
 panel.innerHTML=`<summary>CAD · ustaw narożnik pomieszczenia względem punktu odniesienia</summary><div class="cad-fields"><label>Narożnik przesuwanego pokoju<select id="cadCorner">${corners(r)}</select></label><label>Odniesienie<select id="cadReference"><option value="">Początek układu (0, 0)</option>${data.rooms.filter(q=>q.id!==r.id).map(q=>`<option value="${q.id}">${esc(q.name)} · ${q.elevation||0} mm</option>`).join('')}</select></label><label>Narożnik odniesienia<select id="cadRefCorner" disabled><option value="0">0, 0</option></select></label><label>ΔX → mm<input id="cadX" type="number" step="any"></label><label>ΔY ↓ mm<input id="cadY" type="number" step="any"></label><label>Poziom podłogi · mm<input id="cadLevel" type="number" min="-200000" max="200000" step="any" value="${r.elevation||0}"></label><button id="cadApply">Ustaw narożnik</button></div><p class="cad-help">X w prawo, Y w dół rzutu. Wartości ujemne: lewo / góra. Turkusowy punkt: odniesienie R. Złoty: przesuwany narożnik M. Przesunięcie odłącza istniejące połączenia ścian.</p>`;
 const el=id=>document.getElementById(id),ref=()=>data.rooms.find(q=>q.id===el('cadReference').value)||null;
 const selected=selections.get(r.id);if(selected){el('cadCorner').value=String(Math.min(selected.corner,r.points.length-1));el('cadReference').value=selected.reference;const q=ref();el('cadRefCorner').innerHTML=q?corners(q):'<option value="0">0, 0</option>';el('cadRefCorner').disabled=!q;if(q)el('cadRefCorner').value=String(Math.min(selected.refCorner,q.points.length-1));}
 function points(){const q=ref(),p=r.points[+el('cadCorner').value],a=q?q.points[+el('cadRefCorner').value]:{x:0,y:0};return {m:{x:r.x+p.x,y:r.y+p.y},a:{x:(q?.x||0)+a.x,y:(q?.y||0)+a.y}};}
 function markers(){svg.querySelector('#cadMarkers')?.remove();if(!panel.open)return;const {m,a}=points(),scale=svg.getScreenCTM?Math.hypot(svg.getScreenCTM()?.a||1,svg.getScreenCTM()?.b||0):1,size=7/scale,group=document.createElementNS('http://www.w3.org/2000/svg','g');group.id='cadMarkers';group.setAttribute('pointer-events','none');for(const [p,color,label]of [[a,'#008c91','R'],[m,'#c27b18','M']]){const circle=document.createElementNS(group.namespaceURI,'circle');for(const [k,v]of Object.entries({cx:p.x,cy:p.y,r:size,fill:'white',stroke:color,'stroke-width':2,'vector-effect':'non-scaling-stroke'}))circle.setAttribute(k,v);const t=document.createElementNS(group.namespaceURI,'text');t.setAttribute('x',p.x+size*1.5);t.setAttribute('y',p.y-size*1.5);t.setAttribute('font-size',12/scale);t.setAttribute('fill',color);t.textContent=label;group.append(circle,t);}svg.append(group);}
 function readCurrent(){selections.set(r.id,{corner:+el('cadCorner').value,reference:el('cadReference').value,refCorner:+el('cadRefCorner').value});const {m,a}=points();el('cadX').value=+(m.x-a.x).toFixed(4);el('cadY').value=+(m.y-a.y).toFixed(4);markers();}
 el('cadReference').onchange=()=>{const q=ref();el('cadRefCorner').innerHTML=q?corners(q):'<option value="0">0, 0</option>';el('cadRefCorner').disabled=!q;readCurrent();};el('cadCorner').onchange=readCurrent;el('cadRefCorner').onchange=readCurrent;
 el('cadApply').onclick=()=>{try{const values=['cadX','cadY','cadLevel'].map(id=>{const f=el(id);if(f.value===''||!Number.isFinite(Number(f.value)))throw Error('Wpisz poprawne wartości w mm.');return Number(f.value)});if(Math.abs(values[2])>200000)throw Error('Poziom poza zakresem ±200000 mm.');const next=position(r,+el('cadCorner').value,ref(),+el('cadRefCorner').value,values[0],values[1]);if(next.x!==r.x||next.y!==r.y||values[2]!==(r.elevation||0))data.links=data.links.filter(l=>l.a!==r.id&&l.b!==r.id);Object.assign(r,next,{elevation:values[2]});save();opened=true;render();toast('Ustawiono narożnik zgodnie z odległościami X/Y.');}catch(e){toast(e.message)}};
 panel.ontoggle=()=>{opened=panel.open;markers();};svg.updateCadMarkers=markers;readCurrent();
 };
 if(typeof projectReady!=='undefined'&&projectReady&&view==='plan')render();
})(globalThis);
